Contract ProcessSaleService::enterItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          item:Item = Item.allInstance()->any(o | o.Barcode = barcode)

            precondition:
          CurrentSale.oclIsUndefined() = false and CurrentSale.IsComplete = false and item.oclIsUndefined() = false and item.StockNumber >= quantity

            postcondition:
          { let salesLine:SalesLineItem in salesLine.oclIsNew() and CurrentSale.containedSalesLine->includes(salesLine) and salesLine.BelongedSale = CurrentSale and salesLine.Quantity = quantity and item.StockNumber = item.StockNumber - quantity and salesLine.Subamount = item.Price * quantity and ThirdPartyServices.save(salesLine) and result = true }

        }

