          definition:
          item:Item = Item.allInstance()->any(o | o.Barcode = barcode), salesLine:SalesLineItem = SalesLineItem.allInstance()->any(o | o.oclIsNew()), newStock:Integer = item.StockNumber-quantity, flag:Boolean = true

            precondition:
          CurrentSale.oclIsUndefined() = false and CurrentSale.IsComplete = false and item.oclIsUndefined() = false and item.StockNumber >= quantity

